const input = $input.first().json;
const body = input.body || input;

const outputDir = body.outputDir;
if (!outputDir || !/^[A-Za-z0-9_-]+$/.test(outputDir)) {
  throw new Error('outputDir must be a non-empty string of letters, numbers, "-", "_" only (the folder name under generated/ to "deploy").');
}

const hostPort = Number.isInteger(body.hostPort) ? body.hostPort : 4000;
const safeName = outputDir.toLowerCase().replace(/[^a-z0-9-]/g, '-');

return [{
  json: {
    status: 'ok',
    note: 'DUMMY DEPLOYMENT - this is a placeholder. No Docker image was built, no container was started, and nothing is actually reachable at the URL below.',
    outputDir,
    containerName: 'generated-' + safeName,
    simulatedUrl: 'http://localhost:' + hostPort,
    deployedAt: new Date().toISOString()
  }
}];
